<template>
  <div class="hca-root">
    <!-- ── HERO ──────────────────────────────────────────────────────────── -->
    <div class="hca-hero">
      <div class="hca-hero__left">
        <div class="hca-hero__icon">
          <v-icon color="white" size="22">mdi-account-star</v-icon>
        </div>
        <div>
          <div class="hca-hero__title">HOD Coverage Audit</div>
          <div class="hca-hero__sub">
            Review which Head of Department serves each facility department and
            identify missing or misconfigured assignments
          </div>
        </div>
      </div>
      <div class="hca-hero__stats" v-if="!loading">
        <div class="hca-hero__stat">
          <div class="hca-hero__stat-val">{{ totalItems }}</div>
          <div class="hca-hero__stat-lbl">Facilities</div>
        </div>
        <div class="hca-hero__stat-divider"></div>
        <div class="hca-hero__stat">
          <div class="hca-hero__stat-val">{{ departments.length }}</div>
          <div class="hca-hero__stat-lbl">Departments</div>
        </div>
      </div>
    </div>

    <!-- ── FILTER BAR ─────────────────────────────────────────────────────── -->
    <v-card class="hca-filter-card" flat>
      <v-card-text class="py-3 px-4">
        <v-row dense align="center">
          <!-- Facility name search -->
          <v-col cols="12" sm="6" md="3">
            <v-text-field
              v-model="filters.facilityName"
              label="Search Facility"
              dense
              outlined
              clearable
              hide-details
              prepend-inner-icon="mdi-hospital-building"
              @input="debouncedFetch"
            />
          </v-col>

          <!-- Department multi-select filter -->
          <v-col cols="12" sm="6" md="3">
            <v-autocomplete
              v-model="filters.departments"
              :items="departments"
              item-text="display"
              item-value="code"
              label="Filter Departments"
              dense
              outlined
              clearable
              hide-details
              multiple
              small-chips
              deletable-chips
              prepend-inner-icon="mdi-tag-outline"
              @change="resetAndFetch"
            />
          </v-col>

          <!-- Facility type -->
          <v-col cols="12" sm="6" md="2">
            <v-autocomplete
              v-model="filters.type"
              :items="typeOptions"
              item-text="display"
              item-value="code"
              label="Facility Type"
              dense
              outlined
              clearable
              hide-details
              @change="resetAndFetch"
            />
          </v-col>

          <!-- Status -->
          <v-col cols="12" sm="6" md="2">
            <v-autocomplete
              v-model="filters.status"
              :items="statusOptions"
              item-text="display"
              item-value="code"
              label="Status"
              dense
              outlined
              clearable
              hide-details
              @change="resetAndFetch"
            />
          </v-col>

          <!-- Location treeview -->
          <v-col cols="12" md="2">
            <v-menu
              v-model="locationMenuOpen"
              :close-on-content-click="false"
              offset-y
              min-width="300px"
            >
              <template v-slot:activator="{ on }">
                <v-text-field
                  :value="locationTree.displayValue"
                  label="Filter by Location"
                  dense
                  outlined
                  clearable
                  hide-details
                  readonly
                  prepend-inner-icon="mdi-map-marker-outline"
                  v-on="on"
                  @click:clear="clearLocationTree"
                />
              </template>
              <v-card class="hca-tree-card">
                <v-progress-linear
                  v-if="locationTree.loading"
                  indeterminate
                  color="primary"
                  height="2"
                />
                <v-treeview
                  :active.sync="locationTree.active"
                  :items="locationTree.items"
                  :load-children="fetchLocationChildren"
                  :open.sync="locationTree.open"
                  activatable
                  :multiple-active="false"
                  selection-type="independent"
                  item-key="id"
                  dense
                  hoverable
                >
                  <template v-slot:label="{ item }">
                    <div class="hca-tree-label-row">
                      <v-icon
                        size="13"
                        class="hca-tree-icon"
                        :color="locationNodeColor(item.id)"
                        >{{ locationNodeIcon(item.id) }}</v-icon
                      >
                      <span class="hca-tree-label">{{ item.name }}</span>
                    </div>
                  </template>
                </v-treeview>
              </v-card>
            </v-menu>
          </v-col>
        </v-row>

        <!-- Active filter chips -->
        <div v-if="activeFilterCount > 0" class="hca-chips mt-2">
          <v-chip
            v-if="filters.facilityName"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.facilityName = null;
              resetAndFetch();
            "
          >
            <v-icon x-small left>mdi-hospital-building</v-icon>
            {{ filters.facilityName }}
          </v-chip>
          <v-chip
            v-for="dCode in filters.departments || []"
            :key="dCode"
            x-small
            close
            class="hca-chip hca-chip--dept"
            @click:close="removeDeptFilter(dCode)"
          >
            <v-icon x-small left>mdi-tag-outline</v-icon>
            {{ deptLabel(dCode) }}
          </v-chip>
          <v-chip
            v-if="filters.type"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.type = null;
              resetAndFetch();
            "
            >{{ filters.type }}</v-chip
          >
          <v-chip
            v-if="filters.status"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.status = null;
              resetAndFetch();
            "
            >{{ filters.status }}</v-chip
          >
          <v-chip
            v-if="locationTree.displayValue"
            x-small
            close
            class="hca-chip"
            @click:close="clearLocationTree"
          >
            <v-icon x-small left>mdi-map-marker-outline</v-icon>
            {{ locationTree.displayValue }}
          </v-chip>
          <v-btn
            x-small
            text
            color="grey"
            class="ml-1"
            @click="clearAllFilters"
          >
            Clear all
          </v-btn>
        </div>
      </v-card-text>
    </v-card>

    <!-- ── DATA TABLE ─────────────────────────────────────────────────────── -->
    <v-card class="hca-table-card mt-3" flat>
      <v-data-table
        :headers="headers"
        :items="items"
        :loading="loading"
        :server-items-length="totalItems"
        :options.sync="tableOptions"
        :footer-props="{ 'items-per-page-options': [10, 20, 50] }"
        item-key="facilityId"
        class="hca-table"
        show-expand
        :expanded.sync="expanded"
        @item-expanded="onRowExpanded"
      >
        <template v-slot:progress>
          <v-progress-linear indeterminate color="primary" height="2" />
        </template>

        <!-- Expand toggle column header (blank) -->
        <template v-slot:header.data-table-expand></template>

        <!-- Expand toggle -->
        <template v-slot:item.data-table-expand="{ item, isExpanded, expand }">
          <v-btn
            icon
            x-small
            :class="isExpanded ? 'hca-expand-btn--open' : 'hca-expand-btn'"
            @click="expand(!isExpanded)"
          >
            <v-icon size="16">
              {{ isExpanded ? "mdi-chevron-up" : "mdi-chevron-down" }}
            </v-icon>
          </v-btn>
        </template>

        <!-- Facility name + breadcrumb -->
        <template v-slot:item.facilityName="{ item }">
          <div class="hca-facility-cell">
            <span class="hca-bold">{{ item.facilityName }}</span>
            <div class="hca-breadcrumb">
              <span>{{ item.councilName }}</span>
              <v-icon size="10" color="#a8a29e">mdi-chevron-right</v-icon>
              <span>{{ item.districtName }}</span>
            </div>
          </div>
        </template>

        <!-- Facility type -->
        <template v-slot:item.facilityType="{ item }">
          <v-chip
            v-if="item.facilityType"
            x-small
            label
            color="indigo lighten-5"
            text-color="indigo darken-2"
            >{{ item.facilityType }}</v-chip
          >
          <span v-else class="hca-muted">—</span>
        </template>

        <!-- Status -->
        <template v-slot:item.status="{ item }">
          <div class="d-flex align-center" style="gap:5px">
            <span
              class="hca-status-dot"
              :class="
                item.status === 'active'
                  ? 'hca-status-dot--active'
                  : 'hca-status-dot--inactive'
              "
            ></span>
            <span
              :class="
                item.status === 'active'
                  ? 'hca-status--active'
                  : 'hca-status--inactive'
              "
            >
              {{ item.status || "—" }}
            </span>
          </div>
        </template>

        <!-- HOD summary badge (collapsed view) -->
        <template v-slot:item.hodSummary="{ item }">
          <div class="hca-hod-summary">
            <template v-if="hodCache[item.facilityId]">
              <v-chip
                x-small
                label
                :color="
                  hodCoveredCount(item.facilityId) === activeDepts.length
                    ? 'green lighten-5'
                    : 'orange lighten-5'
                "
                :text-color="
                  hodCoveredCount(item.facilityId) === activeDepts.length
                    ? 'green darken-2'
                    : 'orange darken-3'
                "
              >
                <v-icon x-small left>mdi-account-star</v-icon>
                {{ hodCoveredCount(item.facilityId) }} /
                {{ activeDepts.length }} departments covered
              </v-chip>
            </template>
            <span v-else-if="hodLoading[item.facilityId]" class="hca-muted">
              <v-progress-circular
                size="12"
                width="2"
                indeterminate
                color="primary"
                class="mr-1"
              />
              Loading…
            </span>
            <span v-else class="hca-muted">Expand to load</span>
          </div>
        </template>

        <!-- ── EXPANDED PANEL ───────────────────────────────────────────────── -->
        <template v-slot:expanded-item="{ headers: cols, item }">
          <td :colspan="cols.length" class="hca-expanded-td">
            <!-- Still loading HODs -->
            <div v-if="hodLoading[item.facilityId]" class="hca-expand-loading">
              <v-progress-circular
                size="20"
                width="2"
                indeterminate
                color="primary"
              />
              <span>Loading department heads…</span>
            </div>

            <!-- HOD cards grid -->
            <div v-else class="hca-dept-grid">
              <div
                v-for="dept in activeDepts"
                :key="dept.code"
                class="hca-dept-card"
                :class="
                  getDeptHOD(item.facilityId, dept.code)
                    ? 'hca-dept-card--filled'
                    : 'hca-dept-card--empty'
                "
              >
                <!-- Department label -->
                <div class="hca-dept-card__header">
                  <v-icon
                    size="13"
                    :color="
                      getDeptHOD(item.facilityId, dept.code)
                        ? '#1e40af'
                        : '#d4d4d4'
                    "
                  >
                    mdi-tag-outline
                  </v-icon>
                  <span class="hca-dept-card__label">{{ dept.display }}</span>
                </div>

                <!-- HOD found -->
                <template v-if="getDeptHOD(item.facilityId, dept.code)">
                  <div class="hca-dept-card__person">
                    <v-avatar
                      size="26"
                      color="blue lighten-4"
                      class="mr-2 flex-shrink-0"
                    >
                      <span class="hca-initials indigo--text text--darken-3">
                        {{
                          getInitials(
                            getDeptHOD(item.facilityId, dept.code)
                              .practitionerName,
                          )
                        }}
                      </span>
                    </v-avatar>
                    <div class="hca-dept-card__person-info">
                      <div class="hca-bold hca-dept-card__name">
                        {{
                          getDeptHOD(item.facilityId, dept.code)
                            .practitionerName
                        }}
                      </div>
                      <div class="hca-dept-card__facility">
                        <v-icon size="10" color="#a8a29e"
                          >mdi-hospital-building</v-icon
                        >
                        <span>{{
                          getDeptHOD(item.facilityId, dept.code).facilityname
                        }}</span>
                        <v-chip
                          v-if="
                            getDeptHOD(item.facilityId, dept.code).facility !==
                              item.facilityId
                          "
                          x-small
                          label
                          class="ml-1"
                          color="amber lighten-4"
                          text-color="amber darken-4"
                        >
                          <v-icon x-small left>mdi-swap-horizontal</v-icon>
                          Cross-facility
                        </v-chip>
                      </div>
                    </div>
                  </div>
                </template>

                <!-- No HOD -->
                <div v-else class="hca-dept-card__empty">
                  <v-icon size="16" color="#e5e7eb"
                    >mdi-account-off-outline</v-icon
                  >
                  <span>No HOD assigned</span>
                </div>
              </div>
            </div>
          </td>
        </template>
      </v-data-table>
    </v-card>
    <br />
    <br />
    <br />
  </div>
</template>

<script>
export default {
  name: "HodCoverageAudit",

  data() {
    return {
      loading: false,
      items: [],
      totalItems: 0,
      expanded: [],

      // dept.code → { practitionerName, facility, facilityname } | null
      // keyed as `${facilityId}::${deptCode}`
      hodCache: {},
      hodLoading: {}, // facilityId → true while loading

      tableOptions: {
        page: 1,
        itemsPerPage: 20,
      },

      filters: {
        facilityName: null,
        departments: [], // array of dept codes — filters which depts appear in expanded view
        type: null,
        status: null,
      },

      locationMenuOpen: false,
      locationTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      departments: [], // full list from ValueSet
      typeOptions: [],
      statusOptions: [
        { code: "active", display: "Active" },
        { code: "inactive", display: "Inactive" },
        { code: "suspended", display: "Suspended" },
      ],

      headers: [
        {
          text: "",
          value: "data-table-expand",
          width: "9%",
          sortable: false,
        },
        {
          text: "Facility",
          value: "facilityName",
          sortable: true,
          width: "30%",
        },
        { text: "Type", value: "facilityType", sortable: true, width: "12%" },
        { text: "Status", value: "status", sortable: true, width: "9%" },
        {
          text: "HOD Status",
          value: "hodSummary",
          sortable: false,
          width: "25%",
        },
      ],

      fetchDebounce: null,
    };
  },

  computed: {
    // Departments currently being shown (all if no filter, filtered subset otherwise)
    activeDepts() {
      if (!this.filters.departments || !this.filters.departments.length) {
        return this.departments;
      }
      return this.departments.filter((d) =>
        this.filters.departments.includes(d.code),
      );
    },

    activeFilterCount() {
      return [
        this.filters.facilityName,
        this.filters.departments?.length ? true : null,
        this.filters.type,
        this.filters.status,
        this.locationTree.displayValue,
      ].filter(Boolean).length;
    },
  },

  watch: {
    tableOptions: {
      handler() {
        if (!this._fetchReady) return;
        this.fetchData();
      },
      deep: true,
    },
    "locationTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.locationTree.displayValue = id
        ? this.locationTree.treeLookup[id]?.name || id
        : "";
      this.locationMenuOpen = false;
      this.resetAndFetch();
    },
  },

  async mounted() {
    await Promise.all([
      this.loadLocationTree(),
      this.loadTypeOptions(),
      this.loadDepartments(),
    ]);
    this._fetchReady = true;
    await this.fetchData();
  },

  methods: {
    // ── Fetch facilities (same pattern as HR audit) ─────────────────────────
    async fetchData() {
      this.loading = true;
      this.expanded = []; // collapse all rows on new fetch
      this.hodCache = {}; // invalidate HOD cache when facilities change
      try {
        const { page, itemsPerPage } = this.tableOptions;

        const fhirParams = new URLSearchParams({
          _profile: "http://ihris.org/fhir/StructureDefinition/ls-facility",
          _count: String(itemsPerPage),
          _total: "accurate",
          _offset: String((page - 1) * itemsPerPage),
        });

        if (this.filters.status) fhirParams.set("status", this.filters.status);
        if (this.filters.type) fhirParams.set("type", this.filters.type);
        if (this.filters.facilityName)
          fhirParams.set("name:contains", this.filters.facilityName);

        if (this.locationTree.active.length) {
          const id = this.locationTree.active[0];
          const info = this.locationTree.treeLookup[id];
          if (info?.type === "facility")
            fhirParams.set("_id", id.split("/")[1]);
          else if (info?.type === "council") fhirParams.set("partof", id);
          else fhirParams.set("partof.partof", id);
        }

        const fhirRes = await fetch(`/fhir/Location?${fhirParams}`);
        const bundle = await fhirRes.json();

        const facilities = (bundle.entry || []).map((e) => e.resource);
        // Only overwrite totalItems when the server returns a concrete value —
        // some HAPI versions omit bundle.total on offset pages, which would
        // reset the count to NaN/0 and break Vuetify's pagination controls.
        const serverTotal = Number(bundle.total);
        if (!isNaN(serverTotal) && serverTotal > 0) {
          this.totalItems = serverTotal;
        }

        // Batch-resolve councils + districts
        const councilIds = [
          ...new Set(
            facilities
              .map((f) => f.partOf?.reference?.split("/")?.[1])
              .filter(Boolean),
          ),
        ];
        const resourceById = {};
        if (councilIds.length) {
          const locRes = await fetch(
            `/fhir/Location?_id=${councilIds.join(
              ",",
            )}&_include=Location:partof&_count=500`,
          );
          const locData = await locRes.json();
          for (const entry of locData.entry || []) {
            resourceById[entry.resource.id] = entry.resource;
          }
        }

        this.items = facilities.map((fac) => {
          const councilId = fac.partOf?.reference?.split("/")?.[1];
          const council = councilId ? resourceById[councilId] : null;
          const districtId = council?.partOf?.reference?.split("/")?.[1];
          const district = districtId ? resourceById[districtId] : null;

          return {
            facilityId: fac.id,
            facilityName: fac.name,
            facilityType: fac.type?.[0]?.coding?.[0]?.display || null,
            status: fac.status,
            councilName: council?.name || "—",
            districtId: districtId || null,
            districtName: district?.name || "—",
          };
        });
      } catch (err) {
        console.error("HodCoverageAudit fetchData error", err);
      } finally {
        this.loading = false;
      }
    },

    // ── Expand handler — load HODs for this facility on first expand ────────
    async onRowExpanded({ item, value }) {
      if (!value) return; // collapsing, nothing to do
      const { facilityId, districtId } = item;
      if (this.hodCache[facilityId] || this.hodLoading[facilityId]) return; // already loaded

      this.$set(this.hodLoading, facilityId, true);

      try {
        const depts = this.departments; // all departments

        // Fire one getHOD request per department concurrently
        const results = await Promise.all(
          depts.map(async (dept) => {
            try {
              const params = new URLSearchParams({
                district: districtId,
                facility: facilityId,
                department: dept.code,
              });
              const res = await fetch(`/site/general/getHOD?${params}`);
              const data = await res.json();
              // data is an array; take the first entry that has a practitioner
              const hod = Array.isArray(data)
                ? data.find((h) => h.practitioners.length) || null
                : null;
              return { deptCode: dept.code, hod };
            } catch (_) {
              return { deptCode: dept.code, hod: null };
            }
          }),
        );

        // Resolve practitioner names in a second parallel batch
        const cache = {};
        await Promise.all(
          results.map(async ({ deptCode, hod }) => {
            if (!hod) {
              cache[deptCode] = null;
              return;
            }
            let practitionerName = null;
            if (hod.practitioner) {
              try {
                const pRes = await fetch(
                  `/fhir/Practitioner/${hod.practitioner}`,
                );
                practitionerName = this.parsePractitionerName(
                  await pRes.json(),
                );
              } catch (_) {
                practitionerName = `Practitioner/${hod.practitioner}`;
              }
            }
            cache[deptCode] = { ...hod, practitionerName };
          }),
        );

        // Store under facilityId key — the HOD card grid reads from here
        this.$set(this.hodCache, facilityId, cache);
      } catch (err) {
        console.error(`HOD load failed for facility ${facilityId}:`, err);
        this.$set(this.hodCache, facilityId, {});
      } finally {
        this.$set(this.hodLoading, facilityId, false);
      }
    },

    // ── HOD helpers ─────────────────────────────────────────────────────────
    getDeptHOD(facilityId, deptCode) {
      return this.hodCache[facilityId]?.[deptCode] || null;
    },

    hodCoveredCount(facilityId) {
      const cache = this.hodCache[facilityId];
      if (!cache) return 0;
      return this.activeDepts.filter((d) => cache[d.code]).length;
    },

    // ── Utility ─────────────────────────────────────────────────────────────
    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join("");
    },

    deptLabel(code) {
      return this.departments.find((d) => d.code === code)?.display || code;
    },

    removeDeptFilter(code) {
      this.filters.departments = (this.filters.departments || []).filter(
        (c) => c !== code,
      );
      this.resetAndFetch();
    },

    // ── Fetch / pagination helpers ───────────────────────────────────────────
    debouncedFetch() {
      clearTimeout(this.fetchDebounce);
      this.fetchDebounce = setTimeout(() => {
        if (this.tableOptions.page !== 1) {
          this.tableOptions.page = 1;
        } else {
          this.fetchData();
        }
      }, 350);
    },

    resetAndFetch() {
      if (this.tableOptions.page !== 1) {
        this.tableOptions.page = 1;
      } else {
        this.fetchData();
      }
    },

    // ── Load departments from ValueSet ───────────────────────────────────────
    async loadDepartments() {
      try {
        const res = await fetch(
          "/fhir/ValueSet/departments-valueset/$expand?_count=200",
        );
        const data = await res.json();
        this.departments = (data.expansion?.contains || []).map((c) => ({
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadDepartments error", err);
      }
    },

    // ── Load facility types from ValueSet ────────────────────────────────────
    async loadTypeOptions() {
      try {
        const res = await fetch(
          "/fhir/ValueSet/facility-type-valueset/$expand?_count=200",
        );
        const data = await res.json();
        this.typeOptions = (data.expansion?.contains || []).map((c) => ({
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadTypeOptions error", err);
      }
    },

    // ── Location treeview ────────────────────────────────────────────────────
    async loadLocationTree() {
      if (this.locationTree.items.length) return;
      this.locationTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
            children: [],
          };
          this.locationTree.treeLookup[node.id] = {
            name: node.name,
            type: "district",
          };
          return node;
        });
        this.locationTree.items = nodes;
      } catch (err) {
        console.error("loadLocationTree error", err);
      } finally {
        this.locationTree.loading = false;
      }
    },

    fetchLocationChildren(item) {
      const parentInfo = this.locationTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = [];
            this.locationTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchLocationChildren error", err));
    },

    locationNodeIcon(id) {
      const type = this.locationTree.treeLookup[id]?.type;
      if (type === "district") return "mdi-map-marker-radius";
      if (type === "council") return "mdi-city";
      return "mdi-hospital-building";
    },

    locationNodeColor(id) {
      const type = this.locationTree.treeLookup[id]?.type;
      if (type === "district") return "#1e40af";
      if (type === "council") return "#0e7490";
      return "#16a34a";
    },

    clearLocationTree() {
      this.locationTree.active = [];
      this.locationTree.displayValue = "";
      this.resetAndFetch();
    },

    clearAllFilters() {
      this.filters.facilityName = null;
      this.filters.departments = [];
      this.filters.type = null;
      this.filters.status = null;
      this.locationTree.active = [];
      this.locationTree.displayValue = "";
      this.resetAndFetch();
    },
  },
};
</script>

